package java.util;
import java.util.function.*;
public final class OptionalDouble {private static final OptionalDouble EMPTY=new OptionalDouble();private final boolean present;private final double value;private OptionalDouble(){present=false;value=0;}private OptionalDouble(double v){present=true;value=v;}public static OptionalDouble empty(){return EMPTY;}public static OptionalDouble of(double v){return new OptionalDouble(v);}public double getAsDouble(){if(!present)throw new NoSuchElementException("No value present");return value;}public boolean isPresent(){return present;}public void ifPresent(DoubleConsumer c){if(present)c.accept(value);}public double orElse(double other){return present?value:other;}public double orElseGet(DoubleSupplier s){return present?value:s.getAsDouble();}public <X extends Throwable> double orElseThrow(Supplier<? extends X> s) throws X{if(present)return value;throw s.get();}public boolean equals(Object o){if(!(o instanceof OptionalDouble))return false;OptionalDouble x=(OptionalDouble)o;return present==x.present&&(!present||Double.compare(value,x.value)==0);}public int hashCode(){return present?Double.hashCode(value):0;}public String toString(){return present?"OptionalDouble["+value+"]":"OptionalDouble.empty";}}
